/**
 * Event Bus — in-memory publish/subscribe message broker.
 * Services publish events here; other services subscribe to react.
 */

type EventCallback = (payload: unknown) => void;

export class EventBus {
  private subscribers: Map<string, EventCallback[]> = new Map();

  subscribe(event: string, callback: EventCallback): void {
    if (!this.subscribers.has(event)) {
      this.subscribers.set(event, []);
    }
    this.subscribers.get(event)!.push(callback);
  }

  publish(event: string, payload: unknown): void {
    const callbacks = this.subscribers.get(event);
    if (!callbacks || callbacks.length === 0) return;
    for (const cb of callbacks) {
      try {
        cb(payload);
      } catch (err) {
        console.error(`[EventBus] Error in subscriber for "${event}":`, err);
      }
    }
  }
}

// Singleton instance shared across the application
export const eventBus = new EventBus();

/**
 * User Service — manages user CRUD operations.
 * Owns the in-memory User store.
 * Publishes: none
 * Subscribes: none
 */

import { randomUUID } from "crypto";

export interface User {
  id: string;
  name: string;
  email: string;
}

export class UserService {
  private store: Map<string, User> = new Map();

  create(data: { name: string; email: string }): User {
    if (!data.name || !data.email) {
      throw new Error("name and email are required");
    }
    const user: User = {
      id: randomUUID(),
      name: data.name,
      email: data.email,
    };
    this.store.set(user.id, user);
    return user;
  }

  getById(id: string): User {
    const user = this.store.get(id);
    if (!user) throw new Error(`User not found: ${id}`);
    return user;
  }

  getAll(): User[] {
    return Array.from(this.store.values());
  }

  update(id: string, data: Partial<{ name: string; email: string }>): User {
    const user = this.getById(id);
    if (data.name !== undefined) user.name = data.name;
    if (data.email !== undefined) user.email = data.email;
    this.store.set(id, user);
    return user;
  }

  delete(id: string): void {
    if (!this.store.has(id)) throw new Error(`User not found: ${id}`);
    this.store.delete(id);
  }
}

export const userService = new UserService();

/**
 * Project Service — manages projects and membership.
 * Owns the in-memory Project store.
 * Publishes: none
 * Subscribes: none
 */

import { randomUUID } from "crypto";

export interface Project {
  id: string;
  name: string;
  description: string;
  memberIds: string[];
}

export class ProjectService {
  private store: Map<string, Project> = new Map();

  create(data: { name: string; description: string }): Project {
    if (!data.name) throw new Error("name is required");
    const project: Project = {
      id: randomUUID(),
      name: data.name,
      description: data.description ?? "",
      memberIds: [],
    };
    this.store.set(project.id, project);
    return project;
  }

  getById(id: string): Project {
    const project = this.store.get(id);
    if (!project) throw new Error(`Project not found: ${id}`);
    return project;
  }

  getAll(): Project[] {
    return Array.from(this.store.values());
  }

  update(
    id: string,
    data: Partial<{ name: string; description: string }>
  ): Project {
    const project = this.getById(id);
    if (data.name !== undefined) project.name = data.name;
    if (data.description !== undefined) project.description = data.description;
    this.store.set(id, project);
    return project;
  }

  delete(id: string): void {
    if (!this.store.has(id)) throw new Error(`Project not found: ${id}`);
    this.store.delete(id);
  }

  addMember(id: string, userId: string): Project {
    const project = this.getById(id);
    if (!project.memberIds.includes(userId)) {
      project.memberIds.push(userId);
      this.store.set(id, project);
    }
    return project;
  }

  removeMember(id: string, userId: string): Project {
    const project = this.getById(id);
    project.memberIds = project.memberIds.filter((mid) => mid !== userId);
    this.store.set(id, project);
    return project;
  }
}

export const projectService = new ProjectService();

/**
 * Task Service — manages tasks with status transitions.
 * Owns the in-memory Task store.
 * Publishes: task.assigned, task.statusChanged
 * Subscribes: none
 *
 * Status transitions enforced: todo → in-progress → done (forward only)
 */

import { randomUUID } from "crypto";
import { EventBus } from "../event-bus";

export type TaskStatus = "todo" | "in-progress" | "done";

export interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  assigneeId: string | null;
  projectId: string;
}

// Defines which transitions are allowed (forward only)
const VALID_TRANSITIONS: Record<TaskStatus, TaskStatus[]> = {
  todo: ["in-progress"],
  "in-progress": ["done"],
  done: [],
};

export interface TaskAssignedPayload {
  taskId: string;
  taskTitle: string;
  assigneeId: string;
}

export interface TaskStatusChangedPayload {
  taskId: string;
  taskTitle: string;
  assigneeId: string | null;
  oldStatus: TaskStatus;
  newStatus: TaskStatus;
}

export class TaskService {
  private store: Map<string, Task> = new Map();
  private eventBus: EventBus;

  constructor(eventBus: EventBus) {
    this.eventBus = eventBus;
  }

  create(data: {
    title: string;
    description: string;
    projectId: string;
  }): Task {
    if (!data.title) throw new Error("title is required");
    if (!data.projectId) throw new Error("projectId is required");

    const task: Task = {
      id: randomUUID(),
      title: data.title,
      description: data.description ?? "",
      status: "todo",
      assigneeId: null,
      projectId: data.projectId,
    };
    this.store.set(task.id, task);
    return task;
  }

  getById(id: string): Task {
    const task = this.store.get(id);
    if (!task) throw new Error(`Task not found: ${id}`);
    return task;
  }

  getByProject(projectId: string): Task[] {
    return Array.from(this.store.values()).filter(
      (t) => t.projectId === projectId
    );
  }

  update(
    id: string,
    data: Partial<{ title: string; description: string }>
  ): Task {
    const task = this.getById(id);
    if (data.title !== undefined) task.title = data.title;
    if (data.description !== undefined) task.description = data.description;
    this.store.set(id, task);
    return task;
  }

  delete(id: string): void {
    if (!this.store.has(id)) throw new Error(`Task not found: ${id}`);
    this.store.delete(id);
  }

  assign(id: string, assigneeId: string): Task {
    const task = this.getById(id);
    task.assigneeId = assigneeId;
    this.store.set(id, task);

    const payload: TaskAssignedPayload = {
      taskId: task.id,
      taskTitle: task.title,
      assigneeId,
    };
    this.eventBus.publish("task.assigned", payload);

    return task;
  }

  changeStatus(id: string, newStatus: TaskStatus): Task {
    const task = this.getById(id);
    const allowed = VALID_TRANSITIONS[task.status];

    if (!allowed.includes(newStatus)) {
      throw new Error(
        `Invalid status transition: "${task.status}" → "${newStatus}". ` +
          `Allowed transitions from "${task.status}": [${allowed.join(", ") || "none"}]`
      );
    }

    const oldStatus = task.status;
    task.status = newStatus;
    this.store.set(id, task);

    const payload: TaskStatusChangedPayload = {
      taskId: task.id,
      taskTitle: task.title,
      assigneeId: task.assigneeId,
      oldStatus,
      newStatus,
    };
    this.eventBus.publish("task.statusChanged", payload);

    return task;
  }
}

/**
 * Comment Service — manages comments on tasks.
 * Owns the in-memory Comment store.
 * Publishes: comment.added
 * Subscribes: none
 */

import { randomUUID } from "crypto";
import { EventBus } from "../event-bus";

export interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: string;
}

export interface CommentAddedPayload {
  commentId: string;
  taskId: string;
  taskTitle: string;
  authorId: string;
  authorName: string;
}

export class CommentService {
  private store: Map<string, Comment> = new Map();
  private eventBus: EventBus;

  constructor(eventBus: EventBus) {
    this.eventBus = eventBus;
  }

  /**
   * Creates a comment.
   * taskTitle and authorName must be resolved by the router before calling,
   * since services must not call each other directly.
   */
  create(data: {
    taskId: string;
    authorId: string;
    body: string;
    taskTitle: string;   // resolved by router
    authorName: string;  // resolved by router
  }): Comment {
    if (!data.taskId) throw new Error("taskId is required");
    if (!data.authorId) throw new Error("authorId is required");
    if (!data.body) throw new Error("body is required");

    const comment: Comment = {
      id: randomUUID(),
      taskId: data.taskId,
      authorId: data.authorId,
      body: data.body,
      createdAt: new Date().toISOString(),
    };
    this.store.set(comment.id, comment);

    const payload: CommentAddedPayload = {
      commentId: comment.id,
      taskId: data.taskId,
      taskTitle: data.taskTitle,
      authorId: data.authorId,
      authorName: data.authorName,
    };
    this.eventBus.publish("comment.added", payload);

    return comment;
  }

  getById(id: string): Comment {
    const comment = this.store.get(id);
    if (!comment) throw new Error(`Comment not found: ${id}`);
    return comment;
  }

  getByTask(taskId: string): Comment[] {
    return Array.from(this.store.values()).filter(
      (c) => c.taskId === taskId
    );
  }

  delete(id: string): void {
    if (!this.store.has(id)) throw new Error(`Comment not found: ${id}`);
    this.store.delete(id);
  }
}

/**
 * Notification Service — creates notifications from events.
 * Owns the in-memory Notification store.
 * Publishes: none
 * Subscribes: task.assigned, task.statusChanged, comment.added
 */

import { randomUUID } from "crypto";
import { EventBus } from "../event-bus";
import { TaskAssignedPayload, TaskStatusChangedPayload } from "./task-service";
import { CommentAddedPayload } from "./comment-service";

export interface Notification {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  createdAt: string;
}

export class NotificationService {
  private store: Map<string, Notification> = new Map();

  constructor(eventBus: EventBus) {
    // Subscribe to task.assigned
    eventBus.subscribe("task.assigned", (payload) => {
      const p = payload as TaskAssignedPayload;
      this.createNotification(
        p.assigneeId,
        `You have been assigned to task "${p.taskTitle}".`
      );
    });

    // Subscribe to task.statusChanged
    eventBus.subscribe("task.statusChanged", (payload) => {
      const p = payload as TaskStatusChangedPayload;
      if (p.assigneeId) {
        this.createNotification(
          p.assigneeId,
          `Task "${p.taskTitle}" status changed from "${p.oldStatus}" to "${p.newStatus}".`
        );
      }
    });

    // Subscribe to comment.added
    eventBus.subscribe("comment.added", (payload) => {
      const p = payload as CommentAddedPayload;
      // Notify the task assignee (authorId is the commenter; we notify based on taskId context)
      // The payload includes authorId — we create a notification targeting the author's task context.
      // Per spec: creates notification for task assignee.
      // Since notification service cannot call task service, the router must publish
      // the taskAssigneeId in the event payload. We add it as an optional field.
      const ep = payload as CommentAddedPayload & { taskAssigneeId?: string };
      if (ep.taskAssigneeId) {
        this.createNotification(
          ep.taskAssigneeId,
          `${p.authorName} commented on task "${p.taskTitle}": "${
            (payload as { body?: string }).body ?? "..."
          }"`
        );
      }
      // Always notify the author that their comment was posted
      this.createNotification(
        p.authorId,
        `Your comment on task "${p.taskTitle}" was posted.`
      );
    });
  }

  private createNotification(userId: string, message: string): Notification {
    const notification: Notification = {
      id: randomUUID(),
      userId,
      message,
      read: false,
      createdAt: new Date().toISOString(),
    };
    this.store.set(notification.id, notification);
    return notification;
  }

  getByUser(userId: string): Notification[] {
    return Array.from(this.store.values()).filter(
      (n) => n.userId === userId
    );
  }

  markAsRead(id: string): Notification {
    const notification = this.store.get(id);
    if (!notification) throw new Error(`Notification not found: ${id}`);
    notification.read = true;
    this.store.set(id, notification);
    return notification;
  }
}

